        /// <summary>Тогтвортой нэрээр хайна; олдохгүй бол null.</summary>
        public static ToolMeta Find(string name)
        {
            if (string.IsNullOrEmpty(name)) return null;
            foreach (ToolMeta t in Data)
                if (string.Equals(t.Name, name, StringComparison.Ordinal)) return t;
            return null;
        }

